package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.BeanProperty;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.UnresolvedForwardReference;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId.Referring;
import com.fasterxml.jackson.databind.deser.impl.StdValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.ContainerDeserializerBase;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Collection;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class CollectionDeserializer_createContextual_TriageGen2Test {

    private DeserializationContext ctxt;
    private BeanProperty property;
    private JavaType collectionType;
    private JavaType contentType;
    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        typeFactory = TypeFactory.defaultInstance();
        collectionType = typeFactory.constructCollectionType(Collection.class, String.class);
        contentType = collectionType.getContentType();

        when(ctxt.getConfig()).thenReturn(ctxt.getCodec().getDeserializationConfig());
        when(ctxt.findContextualValueDeserializer(any(), any())).thenReturn(new StdDeserializer<>(Object.class));
    }

    @Test
    public void testCreateContextual_NoInstantiator_NoValueDeser() throws JsonMappingException {
        CollectionDeserializer deser = new CollectionDeserializer(collectionType, null, null, null);

        CollectionDeserializer result = deser.createContextual(ctxt, property);

        assertNotNull(result);
        assertEquals(contentType, result.getContentType());
    }

    @Test
    public void testCreateContextual_WithInstantiator_DelegateTypeNull_ThrowsException() {
        ValueInstantiator instantiator = mock(ValueInstantiator.class);
        when(instantiator.canCreateUsingDelegate()).thenReturn(true);
        when(instantiator.getDelegateType(any())).thenReturn(null);

        CollectionDeserializer deser = new CollectionDeserializer(collectionType, null, null, instantiator);

        try {
            deser.createContextual(ctxt, property);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Invalid delegate-creator definition"));
        } catch (Exception e) {
            fail("Wrong exception type: " + e.getClass().getName());
        }
    }

    @Test
    public void testCreateContextual_WithInstantiator_DelegateSuccess() throws JsonMappingException {
        ValueInstantiator instantiator = mock(ValueInstantiator.class);
        when(instantiator.canCreateUsingDelegate()).thenReturn(true);
        when(instantiator.getDelegateType(any())).thenReturn(contentType);

        // We need to spy the deserializer to mock findDeserializer (which is protected/internal logic)
        CollectionDeserializer deser = spy(new CollectionDeserializer(collectionType, null, null, instantiator));
        JsonDeserializer<Object> delegateDeser = mock(JsonDeserializer.class);
        doReturn(delegateDeser).when(deser).findDeserializer(any(), any(), any());

        CollectionDeserializer result = deser.createContextual(ctxt, property);

        assertNotNull(result);
        verify(deser).findDeserializer(eq(ctxt), eq(contentType), eq(property));
    }

    @Test
    public void testCreateContextual_WithValueDeserializer_HandlesSecondaryContextualization() throws JsonMappingException {
        JsonDeserializer<Object> valueDeser = mock(JsonDeserializer.class);
        CollectionDeserializer deser = new CollectionDeserializer(collectionType, valueDeser, null, null);

        // Mock findConvertingContentDeserializer to return the same (to trigger the 'else' branch)
        CollectionDeserializer spyDeser = spy(deser);
        doReturn(valueDeser).when(spyDeser).findConvertingContentDeserializer(any(), any(), any());

        JsonDeserializer<Object> contextualValueDeser = mock(JsonDeserializer.class);
        when(ctxt.handleSecondaryContextualization(eq(valueDeser), eq(property), eq(contentType)))
                .thenReturn(contextualValueDeser);

        CollectionDeserializer result = spyDeser.createContextual(ctxt, property);

        assertNotNull(result);
        verify(ctxt).handleSecondaryContextualization(valueDeser, property, contentType);
    }

    @Test
    public void testCreateContextual_WithValueDeserializer_FindsContextualValueDeserializer() throws JsonMappingException {
        // valueDeser is null initially
        CollectionDeserializer deser = new CollectionDeserializer(collectionType, null, null, null);

        CollectionDeserializer spyDeser = spy(deser);
        doReturn(null).when(spyDeser).findConvertingContentDeserializer(any(), any(), any());

        JsonDeserializer<Object> contextualValueDeser = mock(JsonDeserializer.class);
        when(ctxt.findContextualValueDeserializer(contentType, property)).thenReturn(contextualValueDeser);

        CollectionDeserializer result = spyDeser.createContextual(ctxt, property);

        assertNotNull(result);
        verify(ctxt).findContextualValueDeserializer(contentType, property);
    }

    @Test
    public void testCreateContextual_WithTypeDeserializer() throws JsonMappingException {
        TypeDeserializer typeDeserializer = mock(TypeDeserializer.class);
        TypeDeserializer forPropertyResult = mock(TypeDeserializer.class);
        when(typeDeserializer.forProperty(property)).thenReturn(forPropertyResult);

        CollectionDeserializer deser = new CollectionDeserializer(collectionType, null, typeDeserializer, null);

        CollectionDeserializer result = deser.createContextual(ctxt, property);

        assertNotNull(result);
        verify(typeDeserializer).forProperty(property);
    }

    @Test
    public void testCreateContextual_AllPaths() throws JsonMappingException {
        // Full complex path
        ValueInstantiator instantiator = mock(ValueInstantiator.class);
        when(instantiator.canCreateUsingDelegate()).thenReturn(true);
        when(instantiator.getDelegateType(any())).thenReturn(contentType);

        JsonDeserializer<Object> valueDeser = mock(JsonDeserializer.class);
        TypeDeserializer typeDeser = mock(TypeDeserializer.class);
        when(typeDeser.forProperty(property)).thenReturn(typeDeser);

        CollectionDeserializer deser = spy(new CollectionDeserializer(collectionType, valueDeser, typeDeser, instantiator));

        JsonDeserializer<Object> delegateDeser = mock(JsonDeserializer.class);
        doReturn(delegateDeser).when(deser).findDeserializer(any(), any(), any());
        doReturn(valueDeser).when(deser).findConvertingContentDeserializer(any(), any(), any());

        JsonDeserializer<Object> secondaryValueDeser = mock(JsonDeserializer.class);
        when(ctxt.handleSecondaryContextualization(eq(valueDeser), eq(property), eq(contentType)))
                .thenReturn(secondaryValueDeser);

        CollectionDeserializer result = deser.createContextual(ctxt, property);

        assertNotNull(result);
        // The result is created via withResolved which uses the protected constructor.
        // Since we can't easily inspect the internal fields of the result without reflection, 
        // we verify the calls that lead to its creation.
        verify(instantiator).getDelegateType(any());
        verify(ctxt).handleSecondaryContextualization(eq(valueDeser), eq(property), eq(contentType));
        verify(typeDeser).forProperty(property);
    }
}
